package net.civeira.phylax.feature.observe.observabilityconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.ObservabilityConfig;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.valueobject.RetentionHoursErrorVO;

class RetentionHoursErrorValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of retention hours error of observability config")
  void test_retention_hours_error_value_holder_assign_plain_value() {
    Object holder = new Object();
    RetentionHoursErrorValueHolder<Object> value = new RetentionHoursErrorValueHolder<>(holder);
    Assertions.assertSame(holder, value.retentionHoursError(1), "Setters must return the holder");
    Assertions.assertTrue(value.getRetentionHoursErrorValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getRetentionHoursError().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of retention hours error of observability config")
  void test_retention_hours_error_value_holder_assign_value_object() {
    Object holder = new Object();
    RetentionHoursErrorValueHolder<Object> value = new RetentionHoursErrorValueHolder<>(holder);
    RetentionHoursErrorVO vo = RetentionHoursErrorVO.from(1);
    Assertions.assertFalse(value.getRetentionHoursErrorValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.retentionHoursError(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRetentionHoursErrorValue().orElseThrow());
    Assertions.assertSame(holder, value.retentionHoursError(Optional.empty()));
    Assertions.assertFalse(value.getRetentionHoursErrorValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.retentionHoursError(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRetentionHoursErrorValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of retention hours error of observability config against the original")
  void test_retention_hours_error_value_holder_read() {
    Object holder = new Object();
    RetentionHoursErrorValueHolder<Object> value = new RetentionHoursErrorValueHolder<>(holder);
    RetentionHoursErrorVO vo = RetentionHoursErrorVO.from(1);
    RetentionHoursErrorVO other = RetentionHoursErrorVO.from(1);
    ObservabilityConfig original = Mockito.mock(ObservabilityConfig.class);
    Mockito.when(original.getRetentionHoursErrorValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRetentionHoursError(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readRetentionHoursError(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.retentionHoursError(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRetentionHoursError(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRetentionHoursError(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of retention hours error of observability config")
  void test_retention_hours_error_value_holder_unset() {
    Object holder = new Object();
    RetentionHoursErrorValueHolder<Object> value = new RetentionHoursErrorValueHolder<>(holder);
    RetentionHoursErrorVO vo = RetentionHoursErrorVO.from(1);
    value.retentionHoursError(vo);
    Assertions.assertSame(holder,
        value.unsetRetentionHoursErrorIfMatches("retentionHoursError_other"));
    Assertions.assertTrue(value.getRetentionHoursErrorValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRetentionHoursErrorIfMatches("retentionHoursError"));
    Assertions.assertFalse(value.getRetentionHoursErrorValue().isPresent(),
        "The field name must clear the value");
    value.retentionHoursError(vo);
    Assertions.assertSame(holder, value.unsetRetentionHoursError());
    Assertions.assertFalse(value.getRetentionHoursErrorValue().isPresent(),
        "Unset must clear the value");
  }
}
